Definition spw_impl_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (R q px vp w i lo : Z) (j7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (R, R + 16); (q + 8, q + 12)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' R [C8 (wz px); C8 (wz q)]
    /\ rw_cells bsegs m' q (SpcHdrCells (mkSPC vp 2 w i) j7).
Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

(* The shadow facts the spw walk reads, carried to the current memory: stack0 for R and R + 8, and
   accessible for WP and q. *)
Lemma spw_side : forall W m mc lo shi WP q,
  ACONST m -> stack0 m lo shi -> accessible m WP 16 -> accessible m q 32 ->
  munch W m mc -> wmono bsegs m mc -> Forall awin W ->
  stack0 mc lo shi /\ accessible mc WP 16 /\ accessible mc q 32.
Proof.
  intros W m mc lo shi WP q AC SK AW AQ MU WM FW.
  assert (SD : aside m lo shi [(WP, 16); (q, 32)] []).
  { split; [exact AC| split; [exact SK| split]].
    - apply Forall_cons; [exact AW| apply Forall_cons; [exact AQ| apply Forall_nil]].
    - apply Forall_nil. }
  destruct (aside_transport _ _ _ _ _ _ _ SD MU WM FW) as (_ & SK' & FA & _).
  pose proof (Forall_inv FA) as A1. pose proof (Forall_inv (Forall_inv_tail FA)) as A2.
  cbn [fst snd] in A1, A2. split; [exact SK'| split; [exact A1| exact A2]].
Qed.

(* Branch closers. Every branch of the walk is data-dependent, so solve_cond cannot decide it: take
   both arms and refute the impossible one explicitly (never `try first [if_false | if_true]`). *)
Local Ltac spw_kill K :=
  exfalso;
  first [ revert K; rewrite ?unsigned_lit by lia; lia
        | vm_compute in K; discriminate
        | vm_compute in K; exact (K eq_refl)
        | vm_compute in K; lia ].
Local Ltac br_nt := let K := fresh "K" in if_cases K; zify_cond K; [ spw_kill K | clear K ].
Local Ltac br_tk := let K := fresh "K" in if_cases K; zify_cond K; [ clear K | spw_kill K ].
Local Ltac sh0 :=
  try replace (zxb (b8 0)) with (Z_to_bv 64 0) by (apply bv_eq; vm_compute; reflexivity);
  try replace (sxb (b8 0)) with (Z_to_bv 64 0) by (apply bv_eq; vm_compute; reflexivity).
(* The shadow byte of g, read from the current memory, by stack0 (stk) or accessible (acc). *)
Local Ltac spw_rd_stk g :=
  lazymatch goal with
  | AC : ACONST ?m, SK : stack0 ?m _ _, AW : accessible ?m _ 16, AQ : accessible ?m _ 32,
    MU : munch _ ?m ?mc, WM : wmono _ ?m ?mc, FW : Forall awin _ |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
      let S := fresh "S" in let RD := fresh "RD" in
      destruct (spw_side _ _ _ _ _ _ _ AC SK AW AQ MU WM FW) as (S & _ & _);
      pose proof (stack0_read0_sr _ _ _ g 8 S ltac:(lia) ltac:(lia) ltac:(lia)) as RD; clear S
  end.
Local Ltac spw_rd_acc A n g :=
  lazymatch goal with
  | AC : ACONST ?m, SK : stack0 ?m _ _, AW : accessible ?m _ 16, AQ : accessible ?m _ 32,
    MU : munch _ ?m ?mc, WM : wmono _ ?m ?mc, FW : Forall awin _ |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
      let A1 := fresh "A1" in let A2 := fresh "A2" in let RD := fresh "RD" in
      destruct (spw_side _ _ _ _ _ _ _ AC SK AW AQ MU WM FW) as (_ & A1 & A2);
      pose proof (accessible_read0_sr _ A n g ltac:(first [exact A1 | exact A2]) ltac:(lia)
                    ltac:(Z.div_mod_to_equations; lia) ltac:(lia)) as RD; clear A1 A2
  end.
(* A shadow check that recomputes the shadow address: srli; add; lb(u); bnez. *)
Local Ltac chk_full := lazymatch goal with RD : ov_read_bytes _ _ _ 1 = _ |- _ => shchk_fast RD end.
(* A shadow check that reloads an address already in a register: lb(u); bnez. *)
Local Ltac chk_reload :=
  lazymatch goal with RD : ov_read_bytes _ _ _ 1 = _ |- _ => step; clear RD; sh0; shchk_br end.

Lemma spw_impl_one_spec : forall (R WP q px vp w i lo shi : Z) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (jr j7 : list byte),
  rw_cells bsegs m R [CB 16 jr] -> bv_unsigned sp <= R -> R + 16 <= shi -> R mod 8 = 0 ->
  ro_cells bsegs m WP [C8 (wz px); C8 (wz q)] -> accessible m WP 16 -> WP mod 8 = 0 -> aapp WP 16 ->
  rw_cells bsegs m q (SpcHdrCells (mkSPC vp 1 w i) j7) -> accessible m q 32 -> aapp q 32 -> q mod 8 = 0 -> 0 < q ->
  0 <= px < 2^64 -> 0 <= vp < 2^64 -> 0 <= w < 2^31 -> (i = 0 \/ i = 1) ->
  (WP + 16 <= q \/ q + 32 <= WP) ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ASPW_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 -> mem_inv bsegs m ->
  ACONST m -> stack0 m lo shi ->
  evt bsegs (spw_impl_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R q px vp w i lo j7 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz R) (wz WP) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_SPW_IMPL) fc None m (seg_rom bsegs)).
Proof.
  intros R WP q px vp w i lo shi ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    F fc m jr j7 RC SPR RHI R8 WPC ACW WP8 APW QC ACQ APQ Q8 Q0 PXR VPR WR IB SEPWQ ST LO CE RA MI AC SK.
  unfold P_B_SPW_IMPL, ASPW_STACK in *.
  unfold SpcHdrCells in QC. cbn [spc_vptr spc_use spc_weak spc_init] in QC. unfold wz in *.
  pose proof (bv_unsigned_in_range 64 sp) as SPB. unfold bv_modulus in SPB. change (2 ^ Z.of_N 64) with (2^64) in SPB.
  pose proof aceil_facts as (AF1 & AF2 & AF3).
  pose proof (aapp_bounds q 32 APQ ltac:(lia)) as QB.
  pose proof (aapp_bounds WP 16 APW ltac:(lia)) as WB.
  pose proof (rw_cells_bound _ _ _ _ QC) as QB2. cbn [cells_size csize Nat.add] in QB2.
  pose proof (rw_cells_bound _ _ _ _ RC) as RB2. cbn [cells_size csize Nat.add] in RB2.
  assert (AMO : amo_aligned AW (Z_to_bv 64 (q + 8)) = true)
    by (apply amo_aligned_intro; [lia | Z.div_mod_to_equations; lia]).
  pose proof (munch_refl [(lo, bv_unsigned sp); (R, R + 16); (q + 8, q + 12)]%Z m) as MU.
  pose proof (wmono_refl bsegs m) as WM.
  assert (FW : Forall awin [(lo, bv_unsigned sp); (R, R + 16); (q + 8, q + 12)]%Z)
    by (repeat apply Forall_cons; [apply awin_stack; lia | apply awin_stack; lia | eapply awin_aapp; [exact APQ| lia| lia] | apply Forall_nil]).
  pose proof (ACONST_shbase _ AC) as [G1 G2]; unfold AGOT_SHBASE, ASHBASE_CELL, wz in G1, G2; rewrite ASHADOW_BASE_val in G2.
  carve_frame 16%nat ST.
  (* addi sp, sp, -16; sd ra, 8(sp); auipc a2; ld a2, 0x404(a2) (the GOT slot); ld a5, 0(a2) (the shadow base) *)
  step. st1. step. step. step.
  (* shadow check for R: srli a4, a0, 3; add a4, a4, a5; lbu a2, 0(a4); bnez a2 *)
  spw_rd_stk R. chk_full.
  (* sd zero, 0(a0) *)
  st1.
  (* addi a3, a1, 8; shadow check for WP + 8 *)
  step. spw_rd_acc WP 16 (WP + 8). chk_full.
  (* addi a2, a0, 8; shadow check for R + 8 (a6 keeps the shadow address) *)
  step. spw_rd_stk (R + 8). chk_full.
  (* ld a3, 0(a3): q; sd a3, 0(a2) *)
  step. st1.
  (* beqz a3: not taken, 0 < q *)
  step. br_nt.
  (* andi a7, a3, 7; bnez a7: not taken, q mod 8 = 0 *)
  step. step.
  let K := fresh "K" in if_cases K; zify_cond K;
    [ exfalso; rewrite XUbsan.land7_mod8, Q8 in K;
      first [ exact (K eq_refl) | vm_compute in K; exact (K eq_refl) ]
    | clear K ].
  (* addi a3, a3, 8 (the use count); shadow check for q + 8 (lb, signed; a7 keeps the shadow address) *)
  step. spw_rd_acc q 32 (q + 8). chk_full.
  (* lw t1, 0(a3): the use count, 1 *)
  step. rewrite ?sx32_lit by lia.
  (* beqz t1: not taken *)
  step. br_nt.
  (* andi t0, a3, 7; addi t0, t0, 3 (the slow shadow path's operands, unused); sext.w t2, t1; addiw t3, t1, 1 *)
  step. step. st1. st1. rewrite ?sx32_lit by lia.
  (* blt t3, t2: not taken, 2 < 1 is false *)
  step. br_nt.
  (* the same shadow byte again, inside the retry loop: lb t1, 0(a7); bnez t1 *)
  spw_rd_acc q 32 (q + 8). chk_reload.
  (* lr.w t1, (a3): the count, 1 *)
  amo_step AMO. rewrite ?sx32_lit by lia.
  (* bne t1, t2: not taken, the lr read the same count *)
  step. br_nt.
  (* sc.w t4, t3, (a3): the reservation is the lr's (one hart), so the count becomes 2 and t4 is 0 *)
  amo_step AMO.
  (* bnez t4: not taken, the sc succeeded *)
  step. br_nt.
  (* beq t1, t2: TAKEN, out of the retry loop to 0xcf34c *)
  step. br_tk.
  (* lbu a3, 0(a6); bnez a3: the shadow byte of R + 8 again *)
  spw_rd_stk (R + 8). chk_reload.
  (* ld a2, 0(a2): q again; beqz a2: not taken *)
  step. step. br_nt.
  (* shadow check for WP: srli a2, a1, 3; add; lbu; bnez *)
  spw_rd_acc WP 16 WP. chk_full.
  (* lbu a2, 0(a4); bnez a2: the shadow byte of R again *)
  spw_rd_stk R. chk_reload.
  (* ld a1, 0(a1): px; sd a1, 0(a0) *)
  step. st1.
  (* ld ra, 8(sp); addi sp, sp, 16; ret *)
  step. release_frame FR ST (bv_unsigned sp). step. step.
  finish.
  all: first [ reflexivity
             | unfold SpcHdrCells; cbn [spc_vptr spc_use spc_weak spc_init]; assumption
             | cbn; repeat (first [exact I | reflexivity | split]) ].
Qed.
